int n = 10;   // ← ここを変えてみよう(0 や 1 も試してみて)

// for: 回数が決まっているくり返し
int sumFor = 0;
for (int i = 1; i <= n; i++) {
    sumFor += i;
}
System.out.println("for      : " + sumFor);

// while: 初期化と更新を自分で書く
int sumWhile = 0;
int k = 1;
while (k <= n) {
    sumWhile += k;
    k++;          // ← これを消すと無限ループ!(10秒でタイムアウトします)
}
System.out.println("while    : " + sumWhile);

// do-while: 最低1回は本体を実行する
int number = 0;   // ← 12345 や 7 に変えてみよう
int digits = 0;
int rest = number;
do {
    digits++;
    rest /= 10;
} while (rest != 0);
System.out.println(number + " は " + digits + " 桁");

int max = 9;   // ← ここを変えてみよう(5 や 12 など)
StringBuilder sb = new StringBuilder();
int count = 0;
for (int i = 1; i <= max; i++) {
    for (int j = 1; j <= max; j++) {
        // if (j == 5) continue;   // ← コメントを外すと 5 の列が飛ばされる
        // if (j > i) break;       // ← コメントを外すと三角形の表になる
        int v = i * j;
        if (v < 10) sb.append(' ');
        if (v < 100) sb.append(' ');
        sb.append(' ').append(v);
        count++;
    }
    sb.append('\n');
}
System.out.print(sb);
System.out.println("内側の本体を実行した回数: " + count);

int value = 98765;   // ← ここを変えてみよう
int digitSum = 0;
int rest = value;
while (rest > 0) {
    int last = rest % 10;   // 一の位
    digitSum += last;
    rest /= 10;             // 一の位を捨てる
}
System.out.println(value + " の各桁の和 = " + digitSum);

long balance = 1_000_000;   // 元本(円)
int rate = 5;               // 年利(%) ← 1 や 0 に変えてみよう
long target = 1_200_000;    // 目標額(円)
int years = 0;
while (balance < target) {
    long interest = balance * rate / 100;   // 1円未満切り捨て
    if (interest == 0) {
        System.out.println("利息が0円なので永遠に届きません");
        break;              // これがないと無限ループ
    }
    balance += interest;
    years++;
    System.out.println(years + "年目: " + balance + "円");
}

// off-by-one: 1〜10 の合計のつもり
int sum = 0;
for (int i = 1; i < 10; i++) {   // ← < を <= に直してみよう
    sum += i;
}
System.out.println("合計: " + sum + "(正しくは 55)");

// double でループ回数を数えると…
int count = 0;
for (double x = 0.0; x < 1.0; x += 0.1) {
    count++;
}
System.out.println("double で数えた回数: " + count + "(10回のつもり)");

// 正しくは整数で数えて、小数は中で計算する
int count2 = 0;
for (int i = 0; i < 10; i++) {
    double x = i / 10.0;
    count2++;
}
System.out.println("int で数えた回数: " + count2);

// 0.1 を10回足すと?
double total = 0.0;
for (int i = 0; i < 10; i++) {
    total += 0.1;
}
System.out.println("0.1 を10回足すと " + total);

